le":null,"status":"inferred"},"caa9ec5228fad8e7":{"confidence":1.0,"evidence_refs":["evidence:0c503a2d5023612c","evidence:96f1b0a349aa457a"],"hypothesis_associations":["mvc"],"kind":"router","label":"router","layer":null,"origin_ref":"framework:HTTP_ENDPOINT:router","related_edge_ids":["200c8453847e1f6a","b0fc145c464f3a14"],"role":null,"status":"observed"},"component:app.py":{"confidence":0.75,"evidence_refs":["evidence:042f72b07d932568","evidence:6eea759f7a3dafc6","evidence:96f1b0a349aa457a","evidence:e72ad51150032838","evidence:f43b587afd6c9331"],"hypothesis_associations":["mvc"],"kind":"component","label":"app.py","layer":null,"origin_ref":"architectural_node:component:app.py","related_edge_ids":["3d97cdcf4c39daeb","9e9e048bc26a9d66"],"role":null,"status":"inferred"},"component:docker-compose.yml":{"confidence":1.0,"evidence_refs":["evidence:2f717a7a2f271d19","evidence:docker_compose:docker-compose.yml:postgres"],"hypothesis_associations":[],"kind":"database","label":"postgres","layer":null,"origin_ref":"architectural_node:component:docker-compose.yml","related_edge_ids":["070069c110eecc0c","870c6bb1abcb03c6"],"role":null,"status":"observed"},"external.fastapi":{"confidence":0.45,"evidence_refs":["evidence:5ccb77c59047c66b","evidence:932edb0686265fcf","evidence:d8a6cd9f26211e0e"],"hypothesis_associations":[],"kind":"external_dependency","label":"FastAPI","layer":null,"origin_ref":"architectural_node:external.fastapi","related_edge_ids":["9e9e048bc26a9d66"],"role":null,"status":"observed"},"infrastructure:compose:docker-compose.yml:postgres":{"confidence":1.0,"evidence_refs":["evidence:docker_compose:docker-compose.yml:postgres"],"hypothesis_associations":[],"kind":"database","label":"postgres","layer":null,"origin_ref":"architectural_node:infrastructure:compose:docker-compose.yml:postgres","related_edge_ids":[],"role":"database","status":"observed"},"repository:visualization_read_model":{"confidence":1.0,"evidence_refs":[],"hypothesis_associations":[],"kind":"repository","label":"visualization_read_model","layer":null,"origin_ref":"architectural_node:repository:visualization_read_model","related_edge_ids":["1159b8f8ffb4d6c5","870c6bb1abcb03c6"],"role":null,"status":"observed"}},"related_edges":{"4ef1f74bfd4c4fae":["200c8453847e1f6a"],"6456eecb59ab5e81":["b0fc145c464f3a14"],"application:visualization_read_model":["070069c110eecc0c","1159b8f8ffb4d6c5","3d97cdcf4c39daeb"],"caa9ec5228fad8e7":["200c8453847e1f6a","b0fc145c464f3a14"],"component:app.py":["3d97cdcf4c39daeb","9e9e048bc26a9d66"],"component:docker-compose.yml":["070069c110eecc0c","870c6bb1abcb03c6"],"external.fastapi":["9e9e048bc26a9d66"],"infrastructure:compose:docker-compose.yml:postgres":[],"repository:visualization_read_model":["1159b8f8ffb4d6c5","870c6bb1abcb03c6"]}};
  const root = document.documentElement;
  const elements = Array.from(root.querySelectorAll(".inspectable"));
  const byId = new Map(elements.map(function (element) {
    return [element.getAttribute("data-read-model-id"), element];
  }));
  const lines = Array.from({length: 32}, function (_, index) {
    return document.getElementById("inspection-line-" + index);
  });
  const defaultLines = [
    "Select a node, edge or hypothesis.",
    "Click Clear to remove the selection."
  ];
  const animationControls = Array.from(root.querySelectorAll(".animation-control"));

  function value(item) {
    return item === null || item === undefined || item === "" ? "UNKNOWN" : String(item);
  }

  function setPanel(items) {
    lines.forEach(function (line, index) {
      line.textContent = index < items.length ? items[index] : "";
    });
  }

  function sourceText(source) {
    if (!source) return ["file: UNKNOWN", "line: UNKNOWN", "symbol: UNKNOWN"];
    const line = source.start_line
      ? (source.end_line && source.end_line !== source.start_line
        ? source.start_line + "-" + source.end_line
        : source.start_line)
      : "UNKNOWN";
    return [
      "file: " + value(source.path),
      "line: " + value(line),
      "symbol: " + value(source.symbol)
    ];
  }

  function evidenceLines(refs, context) {
    const output = ["Evidence (" + context + "):"];
    if (!refs || refs.length === 0) {
      output.push("  UNKNOWN");
      return output;
    }
    refs.forEach(function (ref) {
      const evidence = DATA.evidence[ref];
      if (!evidence) {
        output.push("  " + ref + ": UNKNOWN");
        return;
      }
      output.push("  " + ref + " [" + value(evidence.source_type) + "]");
      output.push("  observation: " + value(evidence.detail));
      output.push("  expression: UNKNOWN");
      output.push("  origin: " + value(evidence.source_type));
      sourceText(evidence.source).forEach(function (part) {
        output.push("  " + part);
      });
    });
    return output;
  }

  function relatedSet(kind, id) {
    const keep = new Set([id]);
    if (kind === "node" && DATA.nodes[id]) {
      DATA.nodes[id].related_edge_ids.forEach(function (edgeId) {
        keep.add(edgeId);
      });
    }
    if (kind === "edge" && DATA.edges[id]) {
      keep.add(DATA.edges[id].source);
      keep.add(DATA.edges[id].target);
    }
    if (kind === "hypothesis") {
      elements.forEach(function (element) {
        const associations = (element.getAttribute("data-hypothesis-associations") || "").split(",");
        if (associations.indexOf(id) >= 0) {
          keep.add(element.getAttribute("data-read-model-id"));
        }
      });
    }
    return keep;
  }

  function select(kind, id) {
    const item = kind === "node" ? DATA.nodes[id]
      : kind === "edge" ? DATA.edges[id]
      : DATA.hypotheses[id];
    if (!item) {
      clear();
      return;
    }
    const keep = relatedSet(kind, id);
    elements.forEach(function (element) {
      const elementId = element.getAttribute("data-read-model-id");
      element.classList.toggle("dimmed", !keep.has(elementId));
      element.classList.toggle("selected", elementId === id);
    });
    let output;
    if (kind === "node") {
      output = [
        "NODE: " + value(item.label),
        "kind: " + value(item.kind),
        "role: " + value(item.role),
        "layer/group: " + value(item.layer),
        "status: " + value(item.status),
        "confidence: " + value(item.confidence),
        "origin: " + value(item.origin_ref),
        "edges: " + value(item.related_edge_ids.join(", ")),
        "hypotheses: " + value(item.hypothesis_associations.join(", "))
      ].concat(evidenceLines(item.evidence_refs, id));
    } else if (kind === "edge") {
      output = [
        "EDGE: " + value(id),
        "source: " + value(item.source),
        "target: " + value(item.target),
        "kind: " + value(item.kind),
        "class: " + value(item.relation_class),
        "status: " + value(item.status),
        "confidence: " + value(item.confidence),
        "origin: " + value(item.origin_ref)
      ].concat(evidenceLines(item.evidence_refs, id));
    } else {
      output = [
        "HYPOTHESIS: " + value(id),
        "status: " + value(item.status),
        "confidence: " + value(item.confidence),
        "explanation: " + value(item.explanation),
        "supporting: " + value(item.supporting_evidence.join(", ")),
        "contradicting: " + value(item.contradicting_evidence.join(", "))
      ].concat(evidenceLines(item.evidence_refs, id));
      item.supporting_evidence.concat(item.contradicting_evidence).forEach(function (ref) {
        if (item.evidence_refs.indexOf(ref) < 0) {
          output.push("evidence ref: " + ref);
        }
      });
    }
    setPanel(output);
  }

  function setMode(mode) {
    const normalized = mode === "animated" ? "animated" : "static";
    root.setAttribute("data-animation-mode", normalized);
    root.classList.remove("mode-static", "mode-animated");
    root.classList.add("mode-" + normalized);
    animationControls.forEach(function (control) {
      const active = control.getAttribute("data-animation-mode") === normalized;
      control.setAttribute("aria-pressed", active ? "true" : "false");
      control.setAttribute("data-active", active ? "true" : "false");
    });
  }

  function clear() {
    elements.forEach(function (element) {
      element.classList.remove("dimmed");
      element.classList.remove("selected");
    });
    setPanel(defaultLines);
  }

  elements.forEach(function (element) {
    element.addEventListener("click", function (event) {
      event.stopPropagation();
      select(element.getAttribute("data-selection-kind"),
        element.getAttribute("data-read-model-id"));
    });
  });
  animationControls.forEach(function (control) {
    control.addEventListener("click", function (event) {
      event.stopPropagation();
      setMode(control.getAttribute("data-animation-mode"));
    });
  });
  Array.from(root.querySelectorAll(".inspect-clear")).forEach(function (element) {
    element.addEventListener("click", function (event) {
      event.stopPropagation();
      clear();
    });
  });
  root.addEventListener("click", function (event) {
    if (event.target === root) clear();
  });
  setMode(root.getAttribute("data-animation-mode") || "static");
  clear();
})();
